// The Changelog tab of the options page: the releases from changelog.json
// (generated by scripts/changelog.mjs from docs/release-notes), newest first,
// up to the version that is running. Opening the tab counts as having seen an
// update, which clears the toolbar badge and the Tutor tab's card (see
// shared/update-notice.js).
//
// An ES module like progress.js, loaded by settings.html.

import { compareVersions, parseVersion } from './shared/version.js';

const api = typeof browser !== 'undefined' ? browser : chrome;

// What the tab shows: every release no newer than `current`, newest first.
// A release for a version that has not shipped yet stays out of sight.
export function releasesUpTo(releases, current) {
  if (!Array.isArray(releases)) return [];
  return releases
    .filter((r) => r && parseVersion(r.version) && Array.isArray(r.items) && compareVersions(r.version, current) <= 0)
    .sort((a, b) => compareVersions(b.version, a.version));
}

export function formatReleaseDate(iso) {
  const date = new Date(`${iso}T12:00:00`);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

function h(tag, attrs, ...children) {
  const node = document.createElement(tag);
  for (const [name, value] of Object.entries(attrs || {})) {
    if (value === false || value === null || value === undefined) continue;
    if (name === 'class') node.className = value;
    else if (name === 'text') node.textContent = value;
    else node.setAttribute(name, value === true ? '' : value);
  }
  for (const child of children) {
    if (child === null || child === undefined || child === false) continue;
    node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
  }
  return node;
}

async function loadReleases() {
  const response = await fetch(api.runtime.getURL('changelog.json'), { cache: 'no-store' });
  if (!response.ok) throw new Error(`changelog.json answered ${response.status}`);
  const body = await response.json();
  return Array.isArray(body.releases) ? body.releases : [];
}

// The update the worker remembers, { from, to }, or null.
async function pendingNotice() {
  try {
    const answer = await api.runtime.sendMessage({ type: 'lc-tutor:update-notice' });
    return answer && answer.ok === true && answer.notice ? answer.notice : null;
  } catch {
    return null;
  }
}

function seen() {
  try {
    Promise.resolve(api.runtime.sendMessage({ type: 'lc-tutor:update-seen' })).catch(() => {});
  } catch {
    // no worker to tell
  }
}

let drawn = false;

// Draws the tab into `panel`, once; opening it again only marks the update
// as seen.
export async function showChangelog(panel) {
  const current = api.runtime.getManifest().version;
  if (drawn) {
    seen();
    return;
  }
  drawn = true;
  let releases;
  try {
    releases = releasesUpTo(await loadReleases(), current);
  } catch {
    drawn = false;
    panel.replaceChildren(
      h('section', { class: 'card' }, h('h2', { text: "What's new" }), h('p', { class: 'result', 'data-kind': 'error', role: 'alert', text: "The list of changes could not be read. Reload this page and try again." }))
    );
    return;
  }
  const notice = await pendingNotice();
  const head = h(
    'section',
    { class: 'card changelog-head', 'aria-labelledby': 'changelog-heading' },
    h('h2', { id: 'changelog-heading', text: "What's new" }),
    h('p', { class: 'help', id: 'changelog-version', text: `You are on version ${current}.` }),
    notice && notice.to === current
      ? h('p', { class: 'notice ok', id: 'changelog-updated', role: 'status', text: notice.from ? `Updated from ${notice.from} to ${notice.to}.` : `Updated to ${notice.to}.` })
      : null
  );
  const cards = releases.map((release) =>
    h(
      'section',
      { class: 'card release', 'data-version': release.version, 'aria-labelledby': `release-${release.version}` },
      h(
        'div',
        { class: 'release-head' },
        h('h3', { id: `release-${release.version}`, text: `Version ${release.version}` }),
        release.version === current ? h('span', { class: 'tag', text: 'Current' }) : null,
        h('span', { class: 'release-date', text: formatReleaseDate(release.date) })
      ),
      h('ul', { class: 'release-items' }, ...release.items.map((item) => h('li', { text: item })))
    )
  );
  panel.replaceChildren(head, ...(cards.length ? cards : [h('p', { class: 'help', text: 'Nothing to show yet.' })]));
  seen();
}
